import{B as e,Q as t,s as n,z as r}from"./chunks/framework.nczTtCLp.js";import"./chunks/admin-expansion-management.gb-3yPAu.js";var i=JSON.parse(`{"title":"Admin Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin-getting-started.md","filePath":"guide/admin-getting-started.md"}`),a={name:`guide/admin-getting-started.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="admin-getting-started" tabindex="-1">Admin Getting Started <a class="header-anchor" href="#admin-getting-started" aria-label="Permalink to &quot;Admin Getting Started&quot;">​</a></h1><p>A step-by-step setup guide for admins: enable AI narration with an API key, and choose which content sets (expansions) your promotion uses. Ten minutes from first login to a working promotion.</p><p><strong>You need:</strong> the ADMIN role (the initial install ships an <code>admin</code> account — change its password first under your user menu) and a web browser.</p><hr><h2 id="step-1-—-open-the-admin-area" tabindex="-1">Step 1 — Open the Admin area <a class="header-anchor" href="#step-1-—-open-the-admin-area" aria-label="Permalink to &quot;Step 1 — Open the Admin area&quot;">​</a></h2><p>Log in and click <strong>Admin</strong> in the navigation. Everything in this tutorial lives under the admin tabs: <strong>AI Settings</strong> and <strong>Expansion Management</strong>.</p><p><img src="/atw-rpg/docs/screenshots/admin-ai-settings.png" alt="Admin AI Settings"></p><hr><h2 id="step-2-—-get-an-api-key-google-gemini-free-tier" tabindex="-1">Step 2 — Get an API key (Google Gemini free tier) <a class="header-anchor" href="#step-2-—-get-an-api-key-google-gemini-free-tier" aria-label="Permalink to &quot;Step 2 — Get an API key (Google Gemini free tier)&quot;">​</a></h2><p>The game&#39;s show narration, commentary, and news generation are powered by an AI provider. Without one configured, the game works but narrates nothing. <strong>Google Gemini&#39;s free tier is enough to start</strong> — no credit card required:</p><ol><li>Go to <a href="https://aistudio.google.com/" target="_blank" rel="noreferrer">Google AI Studio</a> and sign in with a Google account.</li><li>Click <strong>Get API key</strong> → <strong>Create API key</strong> (a new Google Cloud project is created for you automatically).</li><li>Copy the key (starts with <code>AIza…</code>). Treat it like a password — anyone who has it can spend your quota.</li></ol><p>Other providers work exactly the same way — the game supports <strong>OpenAI</strong>, <strong>Claude (Anthropic)</strong>, and <strong>Gemini</strong> out of the box (plus offline <strong>Ollama</strong>/<strong>Mock</strong> providers for testing). Each provider section below shows its own key field; you only need ONE provider enabled.</p><blockquote><p>💡 <strong>Costs:</strong> Gemini&#39;s free tier has daily request limits that are plenty for a single promotion. OpenAI and Claude are paid per request. If you&#39;re evaluating, start with Gemini.</p></blockquote><hr><h2 id="step-3-—-configure-the-provider-in-ai-settings" tabindex="-1">Step 3 — Configure the provider in AI Settings <a class="header-anchor" href="#step-3-—-configure-the-provider-in-ai-settings" aria-label="Permalink to &quot;Step 3 — Configure the provider in AI Settings&quot;">​</a></h2><p>In <strong>Admin → AI Settings</strong>:</p><ol><li>Find the provider section you have a key for (e.g. <strong>Gemini</strong>).</li><li>Tick <strong>Enabled</strong>.</li><li>Paste the key into <strong>API Key</strong>. Fields save as you edit — a notification confirms each change.</li><li>Leave <strong>API URL</strong> and <strong>Model Name</strong> at their defaults unless your provider documents otherwise.</li><li>If you enable more than one provider, leave <strong>Auto Select Provider</strong> ticked and the game picks the first available one.</li></ol><p>Keys are stored in the database and survive restarts. If you run the app in Docker, you can also bootstrap keys with environment variables (<code>AI_GEMINI_API_KEY</code>, <code>AI_OPENAI_API_KEY</code>, <code>AI_CLAUDE_API_KEY</code>) — a value set in the UI always wins over the environment afterward.</p><hr><h2 id="step-4-—-verify-narration-works" tabindex="-1">Step 4 — Verify narration works <a class="header-anchor" href="#step-4-—-verify-narration-works" aria-label="Permalink to &quot;Step 4 — Verify narration works&quot;">​</a></h2><p>The easiest proof is booking any segment and running it: open a show with at least one match (see <a href="./book-your-first-show.html">Book Your First Show</a>) and execute a segment — AI-generated narration appears on the segment when a provider is configured. If narration fails or stays empty, re-check the Enabled box and key first; the application log carries the provider error if it&#39;s deeper.</p><hr><h2 id="step-5-—-enable-your-content-sets-expansion-management" tabindex="-1">Step 5 — Enable your content sets (Expansion Management) <a class="header-anchor" href="#step-5-—-enable-your-content-sets-expansion-management" aria-label="Permalink to &quot;Step 5 — Enable your content sets (Expansion Management)&quot;">​</a></h2><p>Expansions are the game&#39;s content packs: each one bundles wrestler tiers, match types, segment rules, and title lineages. <strong>Admin → Expansion Management</strong> lists them with an enable toggle per set.</p><p><img src="/atw-rpg/docs/screenshots/admin-expansion-management.png" alt="Admin Expansion Management"></p><ul><li><strong>Start small:</strong> enable the base set plus one or two that fit the era you want to book. Every enabled set widens the match types, rules, and titles bookers see when planning shows.</li><li>Disabling a set does not delete data — it hides that content from planning. Re-enabling brings it back.</li><li>Two expansions defining the same match type or rule resolve by <strong>priority</strong> (higher wins), so overlaps are safe to enable together.</li></ul><hr><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li>Hand the booker role to your first booker and walk them through <a href="./book-your-first-show.html">Book Your First Show</a>.</li><li>The auto-generated <a href="./admin.html">Admin Overview</a> documents every admin screen in depth.</li></ul>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};